void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    uv.y = 1.0 - uv.y; // Flip Y coordinates

    // Create a grainy effect
    float grain = fract(sin(dot(uv * 50.0, vec2(12.9898, 78.233))) * 43758.5453);
    float noise = smoothstep(0.2, 0.8, grain);

    // Generate random rotation angle
    float angle = sin((iTime*.1+iMouse.x*.001) + uv.x * 5.0) * 1.5;

    // Triangle distortion with less intensity
    vec2 rotatedUV = vec2(
        uv.x * cos(angle) - uv.y * sin(angle),
        uv.x * sin(angle) + uv.y * cos(angle)
    );

    float triangle = abs(fract(rotatedUV.x * 2.0) * 2.0 - 1.0);

    // Line effect with less frequency
    float line = step(0.15, fract(rotatedUV.y * 5.0*(iMouse.y*.001+.00001)));

    // Negative colors filter
    vec3 color = mix(vec3(1.0, 1.0, 1.0), vec3(0.0, 0.0, 0.0), triangle * line);
    color *= 1.0 - noise * 0.1;

    fragColor = vec4(1.0 - color, 1.0); // Apply negative color filter
}
